INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(46911, 'Proverbs 22:21', 'Proverbs', 22, 21, 'ترڅو تا پوه کړم چې رښتیا او د باور وړ خبرې زده کړې او هغه چاته رښتینی ځواب ورکړې چې ته یې رالېږلی یې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs22_verse_21.mp3', '', 1761754199, 1761754199),
(46912, 'Proverbs 22:22', 'Proverbs', 22, 22, 'د غریب د غریبۍ نه په غلا غلطه ګټه مه اخله او په محکمه کې د مسکینانو حق تر‌پښو مه لاندې کوه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs22_verse_22.mp3', '', 1761754199, 1761754199),
(46913, 'Proverbs 22:23', 'Proverbs', 22, 23, 'ځکه څښتن به د دوی د حق ساتنه وکړي او هغوی به تباه کړي چې د دوی نه یې غلا کړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs22_verse_23.mp3', '', 1761754199, 1761754199),
(46914, 'Proverbs 22:24', 'Proverbs', 22, 24, 'د غوسه ناک انسان سره ناسته ولاړه مه کوه او د هغه چا سره ملګرتیا مه کوه چې زر په قهریږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs22_verse_24.mp3', '', 1761754199, 1761754199),
(46915, 'Proverbs 22:25', 'Proverbs', 22, 25, 'هسې نه چې د هغه عادتونه زده کړې او خپل ځان په دام کې ونښلوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs22_verse_25.mp3', '', 1761754199, 1761754199),
(46916, 'Proverbs 22:26', 'Proverbs', 22, 26, 'د بل چا په قرض کې لاس مه ورکوه او مه د چا د پور ضمانت په خپله غاړه اخله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs22_verse_26.mp3', '', 1761754199, 1761754199),
(46917, 'Proverbs 22:27', 'Proverbs', 22, 27, 'که ته چېرته دا قرض ورنه کړې نو د خوب کټ او بستره به درنه یوسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs22_verse_27.mp3', '', 1761754199, 1761754199),
(46918, 'Proverbs 22:28', 'Proverbs', 22, 28, 'د ځمکې د حد پخوانۍ تیږه مه بېځایه کوه کوم چې پلار او نیکه دې پخوا ایښودلې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs22_verse_28.mp3', '', 1761754199, 1761754199),
(46919, 'Proverbs 22:29', 'Proverbs', 22, 29, 'څوک چې په خپل کار کې مهارت ولري د پاچاهانو په حضور کې به خدمت کوي او د عامو خلکو خدمت به نه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs22_verse_29.mp3', '', 1761754199, 1761754199),
(46920, 'Jeremiah 43:1', 'Jeremiah', 43, 1, 'کله چې يرمياه د مالِک خُدائ د دوئ د خُدائ پاک هغه پېغام بيانول ټولو خلقو ته ختم کړو کوم يې چې دوئ ته رالېږلے وو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah43_verse_1.mp3', '', 1761754199, 1761754199),
(46921, 'Jeremiah 43:2', 'Jeremiah', 43, 2, 'نو عزرياه د هوسعياه زوئ او يوحانان د قريح زوئ او نورو ټولو کبرژنو خلقو يرمياه ته ووئيل چې، ”تۀ دروغ وائې، مالِک خُدائ زمونږ خُدائ پاک مونږ کله هم مِصر ته د تلو نه منع کړى نۀ يُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah43_verse_2.mp3', '', 1761754199, 1761754199),
(46922, 'Jeremiah 43:3', 'Jeremiah', 43, 3, 'تۀ باروک د نيرياه زوئ په دې رضا کړے يې چې داسې خبرې کوه، ځکه هغه غواړى چې مونږ دلته پاتې شُو او د بابليانو د لاسه مړۀ شُو او يا بابل ته جلاوطن کړے شُو.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah43_verse_3.mp3', '', 1761754199, 1761754199),
(46923, 'Jeremiah 43:4', 'Jeremiah', 43, 4, 'نو بيا د قريح زوئ يوحانان او نورو فوجى مشرانو او نورو ټولو خلقو د مالِک خُدائ د حکم نه اِنکار وکړو چې په يهوداه کښې پاتې شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah43_verse_4.mp3', '', 1761754199, 1761754199),
(46924, 'Jeremiah 43:5', 'Jeremiah', 43, 5, 'يوحنان او نورو مشرانو ځان سره ټول خلق بوتلل څوک چې د نزدې مُلکونو نه راواپس شوى وُو کوم ځائ ته چې دوئ خوارۀ شوى وُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah43_verse_5.mp3', '', 1761754199, 1761754199),
(46925, 'Jeremiah 43:6', 'Jeremiah', 43, 6, 'او په هغوئ کښې نارينه، زنانه، ماشومان، د بادشاه لوڼه، او ټول هغه خلق شامل وُو چې نبوزردان د محافظانو آفسر جدلياه ته سپارلى وُو. په دوئ کښې يرمياه پېغمبر او باروک هم شامل وُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah43_verse_6.mp3', '', 1761754199, 1761754199),
(46926, 'Jeremiah 43:7', 'Jeremiah', 43, 7, 'خلقو د مالِک خُدائ د حکم نه اِنکار وکړو او د مِصر تحفنحيس ښار ته ورسېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah43_verse_7.mp3', '', 1761754199, 1761754199),
(46927, 'Jeremiah 43:8', 'Jeremiah', 43, 8, 'په تحفنحيس کښې مالِک خُدائ يرمياه ته بل پېغام ورکړو. هغۀ وفرمائيل چې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah43_verse_8.mp3', '', 1761754199, 1761754199),
(46928, 'Jeremiah 43:9', 'Jeremiah', 43, 9, '”کله چې د يهوداه خلق درته ګورى، نو دلته په تحفنحيس کښې يو څو غټ کاڼى راواخله او د فِرعون د محل په دروازه کښې يې د فرش لاندې ښخ کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah43_verse_9.mp3', '', 1761754199, 1761754199),
(46929, 'Jeremiah 43:10', 'Jeremiah', 43, 10, 'نو بيا د يهوداه خلقو ته ووايه چې، مالِک خُدائ ربُ الافواج د بنى اِسرائيلو خُدائ پاک داسې فرمائى چې زۀ به په يقين سره خپل خِدمتګار نبوکدنضر د بابل بادشاه دلته مِصر ته راولم. زۀ به د هغۀ تخت په دې کاڼو دپاسه جوړ کړم کوم چې يرمياه دلته ښخ کړل. هغه به په دې کاڼو خپل شاهى تمبو وغوړوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah43_verse_10.mp3', '', 1761754199, 1761754199),
(46930, 'Jeremiah 43:11', 'Jeremiah', 43, 11, 'او کله چې هغه راشى، نو هغه به د مِصر مُلک تباه کړى. هغه څوک به مړ کړى د چا دپاره چې د مرګ سزا مقرر شوې وى، د قېد سزا به هغۀ ته ورکړى چا ته چې د قېد سزا مقرر شوې وى، او څوک به په تُوره مړۀ کړى د چا دپاره چې په تُوره مړ کېدل مقرر شوى وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah43_verse_11.mp3', '', 1761754199, 1761754199),
(46931, 'Jeremiah 43:12', 'Jeremiah', 43, 12, 'هغه به د مِصر د معبودانو په مندرونو اور بل کړى، هغه به مندرونه وسوزوى او بُتان به قبضه کړى او د غنيمت په توګه به يې يوسى. هغه به د مِصر مال متاع داسې صفا کړى لکه څنګه چې يو شپون د خپلې چُوغې نه ورَږې صفا کوى. او بې‌نقصانه به هغه خپل مُلک ته واپس شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah43_verse_12.mp3', '', 1761754199, 1761754199),
(46932, 'Jeremiah 43:13', 'Jeremiah', 43, 13, 'هغه به د مِصر په بيت‌شمس مندر کښې مقدسې ستنې راوغورزوى کومې چې په هغې کښې ولاړې دى، او هغه به د مِصر د معبودانو مندرونه وسوزوى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah43_verse_13.mp3', '', 1761754199, 1761754199),
(46933, 'Jeremiah 52:1', 'Jeremiah', 52, 1, 'صدقياه د يويشتو کالو وو کله چې هغه د يهوداه بادشاه شو، او هغۀ په يروشلم يوولس کاله بادشاهى وکړه. د هغۀ د مور نامه حموطل وه، چې د يرمياه لور وه، چې هغه د لِبناه وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah52_verse_1.mp3', '', 1761754199, 1761754199),
(46934, 'Jeremiah 52:2', 'Jeremiah', 52, 2, 'خو هغۀ د مالِک خُدائ په وړاندې هغه بدکارونه وکړل، کوم چې يهويقيم بادشاه کړى وُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah52_verse_2.mp3', '', 1761754199, 1761754199),
(46935, 'Jeremiah 52:3', 'Jeremiah', 52, 3, 'دا هر څۀ د يروشلم او يهوداه سره د مالِک خُدائ د قهر په وجه وشول، او په آخر کښې هغۀ هغوئ د خپل حضور نه وشړل. خو اوس صدقياه د بابل بادشاه خلاف سرکشى وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah52_verse_3.mp3', '', 1761754199, 1761754199),
(46936, 'Jeremiah 52:4', 'Jeremiah', 52, 4, 'نو د صدقياه بادشاه د حکومت په نهم کال، په لسمه ورځ د لسمې مياشتې نبوکدنضر د بابل بادشاه د خپل ټول فوج سره په يروشلم حمله وکړه. هغوئ ښار محاصره کړو او د دې د دېوالونو نه يې ګېرچاپېره مورچې جوړې کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah52_verse_4.mp3', '', 1761754199, 1761754199),
(46937, 'Jeremiah 52:5', 'Jeremiah', 52, 5, 'يروشلم د صدقياه بادشاه د حکومت تر يوولسم کال پورې محاصره وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah52_verse_5.mp3', '', 1761754199, 1761754199),
(46938, 'Jeremiah 52:6', 'Jeremiah', 52, 6, 'د څلورمې مياشتې په نهمه ورځ د صدقياه د حکومت په يوولسم کال، په ښار کښې قحطى ډېره سخته شوه، او آخر يې ټول خوراک بلکل ختم شوے وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah52_verse_6.mp3', '', 1761754199, 1761754199),
(46939, 'Jeremiah 52:7', 'Jeremiah', 52, 7, 'بيا د ښار د دېوال يوه حِصه راوغورزولے شوه او ټول فوجيان وتښتېدل. خو دا چې بابليانو ښار محاصره کړے وو، نو هغوئ د شپې د تيارې انتظار کولو. نو بيا هغوئ د بادشاه د باغ وروستو دوو دېوالونو په مينځ کښې دروازې نه وتښتېدل او د اُردن وادۍ طرف ته يې مخه وتړله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah52_verse_7.mp3', '', 1761754199, 1761754199),
(46940, 'Jeremiah 52:8', 'Jeremiah', 52, 8, 'خو د بابليانو فوجيانو صدقياه بادشاه پسې راخستې وه او هغه يې د يريحو په مېدانونو کښې ونيولو، د هغۀ سړو هغه پرېښودو او خوارۀ وارۀ شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah52_verse_8.mp3', '', 1761754199, 1761754199),
(46941, 'Jeremiah 52:9', 'Jeremiah', 52, 9, 'هغوئ هغه د بابل بادشاه ته رِبله ته بوتلو چې د حمات په مُلک کښې وو. د بابل بادشاه بيا د سزا ورکولو خپله فېصله په صدقياه واوروله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah52_verse_9.mp3', '', 1761754199, 1761754199),
(46942, 'Jeremiah 52:10', 'Jeremiah', 52, 10, 'هغوئ د صدقياه په مخامخ د هغۀ زامن او د يهوداه ټول آفسران حلال کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah52_verse_10.mp3', '', 1761754199, 1761754199),
(46943, 'Jeremiah 52:11', 'Jeremiah', 52, 11, 'نو هغوئ د صدقياه سترګې وويستلې، د پيتلو په زنځيرونو يې وتړلو او بابل ته يې بوتلو چرته چې هغه د خپل مرګ تر وخته پورې هلته پروت وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah52_verse_11.mp3', '', 1761754199, 1761754199),
(46944, 'Jeremiah 52:12', 'Jeremiah', 52, 12, 'د پينځمې مياشتې په لسمه ورځ په نولسم کال د بابل د بادشاه نبوکدنضر، شاهى کمانډر نبوزردان چې د شاهى فوج مشر وو، يروشلم ته راغلو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah52_verse_12.mp3', '', 1761754199, 1761754199),
(46945, 'Jeremiah 52:13', 'Jeremiah', 52, 13, 'هغۀ د مالِک خُدائ په عبادتګاه، په شاهى محل او د يروشلم په ټولو کورونو اور ولګولو. هر يو خاص عمارت هغۀ وسوزولو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah52_verse_13.mp3', '', 1761754199, 1761754199),
(46946, 'Jeremiah 52:14', 'Jeremiah', 52, 14, 'او د بابل ټولو فوجيانو د شاهى کمانډر په مشرۍ کښې د يروشلم د ښار ګېرچاپېره دېوالونه راوغورزول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah52_verse_14.mp3', '', 1761754199, 1761754199),
(46947, 'Jeremiah 52:15', 'Jeremiah', 52, 15, 'نو بيا نبوزردان د بابل فوجى کمانډر هغه ځينې غريبانان خلق جلاوطن کړل او نور هغه کسان چې په ښار کښې پاتې وُو، او هم نور ماهِر کاريګران، او هغوئ څوک چې د بابل د بادشاه بګوړه شوى وُو هم بوتلل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah52_verse_15.mp3', '', 1761754199, 1761754199),
(46948, 'Jeremiah 52:16', 'Jeremiah', 52, 16, 'خو نبوزردان څۀ غريبانان خلق په مُلک کښې پرېښودل کوم چې بلکل غريبانان وُو ترڅو هغوئ د انګورو په باغونو او پټو کښې کار وکړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah52_verse_16.mp3', '', 1761754199, 1761754199),
(46949, 'Jeremiah 52:17', 'Jeremiah', 52, 17, 'بابليانو هغه د زېړو ستنې ماتې کړې، او هغه ګاډۍ او د زېړو تالاب چې نوم يې سمندر وو، کوم چې د مالِک خُدائ په کور کښې وو او هغوئ ټول زېړ د خپل ځان سره بابل ته يوړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah52_verse_17.mp3', '', 1761754199, 1761754199),
(46950, 'Jeremiah 52:18', 'Jeremiah', 52, 18, 'هغوئ د خپل ځان سره ټول هغه سامان يوړلو کوم به چې د خُدائ په کور کښې د خِدمت کولو دپاره استعمالېدلو، لکه بېلچې او د ايرو لوښى، د ډيوو سرپوښونه، چمچۍ، د قربانۍ د وينې اوچتولو جامونه، پيالۍ، د خوشبويۍ سوزولو لوښى او د زېړو نور ټول سامان يې لوټ کړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah52_verse_18.mp3', '', 1761754199, 1761754199),
(46951, 'Jeremiah 52:19', 'Jeremiah', 52, 19, 'نبوزردان د فوج مشر ځان سره هم هغه وړې کاسې، د خوشبو انګيټۍ، کاسې، دېګونه، ډيوټ دانونه، لوښى، کاسې کومې چې چڼکاو نذرانو دپاره استعمالېدلې او نور ټول سامان کوم چې د سوچه سرو او سپينو زرو نه جوړې شوې وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah52_verse_19.mp3', '', 1761754199, 1761754199),
(46952, 'Jeremiah 52:20', 'Jeremiah', 52, 20, 'هغه زېړ چې کوم په ستنو کښې وُو، د زېړو سمندر او هغه دولس غوَيان چې ورلاندې جوړ شوى وُو، هغه ستنې، کومې چې سليمان بادشاه د مالِک خُدائ د کور دپاره جوړې کړې وې، دومره زيات درانۀ وُو چې وزن کولو نه بهر وُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah52_verse_20.mp3', '', 1761754199, 1761754199),
(46953, 'Jeremiah 52:21', 'Jeremiah', 52, 21, 'دواړه ستنې يو شان وې، هره يوه تقريباً نهۀ ګزه اوچته او تقريباً شپږ ګزه ګول وه، د هغوئ مينځ خالى وو خو د هغوئ د دېوال ګېج تقريباً درې اِنچه غټ وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah52_verse_21.mp3', '', 1761754199, 1761754199),
(46954, 'Jeremiah 52:22', 'Jeremiah', 52, 22, 'د هرې يوې ستنې په سر باندې تقريباً درې ګزه اوچت د زېړو تاج وو چې دا ګېرچاپېره د زېړو په زنځيرونو تړلى شوى انارو ښائسته کړے شوے وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah52_verse_22.mp3', '', 1761754199, 1761754199),
(46955, 'Jeremiah 52:23', 'Jeremiah', 52, 23, 'د هرې ستنې نه ګېرچاپېره شپږ نوې انار لګولے شوى وُو چې ټوټل سل انار ورباندې لګولے شوى وُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah52_verse_23.mp3', '', 1761754199, 1761754199),
(46956, 'Jeremiah 52:24', 'Jeremiah', 52, 24, 'نبوزردان د فوج مشر د خپل ځان سره د دې نه علاوه، مشر اِمام شراياه، ورپسې اِمام صفنياه او د مالِک خُدائ د کور نور درې خادمان قېديان بوتلل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah52_verse_24.mp3', '', 1761754199, 1761754199),
(46957, 'Jeremiah 52:25', 'Jeremiah', 52, 25, 'د ښار نه هغۀ هغه آفسر بوتلو کوم چې د جنګى فوجيانو مشر وو، او اووۀ د بادشاه ذاتى مشيران چې هغوئ لا تر اوسه په ښار کښې وُو، د فوجى مشر منشى چې هغه د فوجيانو د بهرتى کولو ذمه وار وو او شپېتۀ نور اهم سړى يې هم بوتلل،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah52_verse_25.mp3', '', 1761754199, 1761754199),
(46958, 'Jeremiah 52:26', 'Jeremiah', 52, 26, 'نبوزردان هغوئ ټول ځان له کړل او د صوبه حمات په رِبله ښار کښې يې د بابل بادشاه له بوتلل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah52_verse_26.mp3', '', 1761754199, 1761754199),
(46959, 'Jeremiah 52:27', 'Jeremiah', 52, 27, 'او هلته په رِبله کښې د حمات په زمکه د بابل بادشاه ټول ووژل. نو بيا داسې د يهوداه خلق د خپل مُلک نه پردى مُلک ته بوتلے شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah52_verse_27.mp3', '', 1761754199, 1761754199),
(46960, 'Jeremiah 52:28', 'Jeremiah', 52, 28, 'د نبوکدنضر د حکومت په اوؤم کال کښې څوک چې جلاوطن کړے شوى وُو د هغوئ شمېر درې زره او درويشت وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah52_verse_28.mp3', '', 1761754199, 1761754199),
(46961, 'Jeremiah 52:29', 'Jeremiah', 52, 29, 'او د نبوکدنضر په اتلسم کال د حکومت په دوران کښې نور اتۀ سوه او دوه دېرش کسان د يروشلم نه قېديان بوتلل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah52_verse_29.mp3', '', 1761754199, 1761754199),
(46962, 'Jeremiah 52:30', 'Jeremiah', 52, 30, 'او د نبوکدنضر د حکومت په درويشتم کال هغه نبوزردان راولېږلو او هغۀ نور اووۀ سوه او پينځۀ څلوېښت کسان قېديان بوتلل چې د ټولو شمېر څلور زره او شپږ سوه کسان شُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah52_verse_30.mp3', '', 1761754199, 1761754199),
(46963, 'Jeremiah 52:31', 'Jeremiah', 52, 31, 'د جلاوطنۍ په اووۀ دېرشم کال يهوياکين د يهوداه بادشاه په کوم کال چې اويل‌مرودک د بابل بادشاه شو، نو هغۀ د يهوداه بادشاه په يهوياکين رحم وکړو او هغه يې د قېدخانې نه د دولسمې مياشتې په پينځويشتمه ورځ آزاد کړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah52_verse_31.mp3', '', 1761754199, 1761754199),
(46964, 'Jeremiah 52:32', 'Jeremiah', 52, 32, 'اويل‌مرودک د هغۀ سره ښۀ سلوک وکړو او د هغه نورو بادشاهانو نه يې هم د لوئ عزت ځائ ورکړو کوم چې د هغۀ سره په بابل کښې جلاوطن وُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah52_verse_32.mp3', '', 1761754199, 1761754199),
(46965, 'Jeremiah 52:33', 'Jeremiah', 52, 33, 'نو يهوياکين خپلې د قېدخانې جامې يو خوا ته وويستلې او باقى ټول عمر يې د بادشاه په مېز باندې خوړل څښل کول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah52_verse_33.mp3', '', 1761754199, 1761754199),
(46966, 'Jeremiah 52:34', 'Jeremiah', 52, 34, 'هره ورځ د بابل بادشاه يهوياکين ته باقاعده خرچه ورکوله او هغۀ ورته تر مرګه پورې خرچه مقرره کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah52_verse_34.mp3', '', 1761754199, 1761754199),
(46967, 'Leviticus 18:1', 'Leviticus', 18, 1, 'څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus18_verse_1.mp3', '', 1761754199, 1761754199),
(46968, 'Leviticus 18:2', 'Leviticus', 18, 2, '«د اسراییلو د خلکو سره خبرې وکړه او ورته ووایه چې زه ستاسو څښتن خدای یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus18_verse_2.mp3', '', 1761754199, 1761754199),
(46969, 'Leviticus 18:3', 'Leviticus', 18, 3, 'د مصر د خلکو په شان کار مه کوئ چې یو وخت تاسو په کې اوسېدلئ، یا د کنعان د خلکو په شان کار مه کوئ چې زه اوس تاسو هلته بیایم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus18_verse_3.mp3', '', 1761754199, 1761754199),
(46970, 'Leviticus 18:4', 'Leviticus', 18, 4, 'تاسو باید زما قوانینو ته غاړه کېږدئ او زما د فرمانونو له مخې عمل وکړئ. زه ستاسو څښتن خدای یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus18_verse_4.mp3', '', 1761754199, 1761754199),
(46971, 'Leviticus 18:5', 'Leviticus', 18, 5, 'زما په فرمانونو او قوانینو باندې عمل وکړئ، ځکه څوک چې هغو ته غاړه کېږدي د هغو په وسیله به ژوند وکړي. زه څښتن یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus18_verse_5.mp3', '', 1761754199, 1761754199),
(46972, 'Leviticus 18:6', 'Leviticus', 18, 6, 'هېڅوک دې د خپلو نژدې خپلوانو سره زنا نه کوي. زه څښتن یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus18_verse_6.mp3', '', 1761754199, 1761754199),
(46973, 'Leviticus 18:7', 'Leviticus', 18, 7, 'د خپلې مور سره په زنا کولو سره د خپل پلار سپکاوی مه کوئ. هغه ستاسو مور ده، د هغې سره زنا مه کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus18_verse_7.mp3', '', 1761754199, 1761754199),
(46974, 'Leviticus 18:8', 'Leviticus', 18, 8, 'د خپل پلار د نورو ښځو سره په زنا کولو سره د خپل پلار سپکاوی مه کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus18_verse_8.mp3', '', 1761754199, 1761754199),
(46975, 'Leviticus 18:9', 'Leviticus', 18, 9, 'د خپلې سکه یا ناسکه خور سره که هغه ستاسو د پلار لور وي یا د مور، که هغه تاسو سره په یو کور کې زېږېدلې وي یا په بل ځای کې، د هغې سره زنا مه کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus18_verse_9.mp3', '', 1761754199, 1761754199),
(46976, 'Leviticus 18:10', 'Leviticus', 18, 10, 'د خپلې لمسۍ سره زنا مه کوئ، هغه به ستاسو دپاره سپکاوی وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus18_verse_10.mp3', '', 1761754199, 1761754199),
(46977, 'Leviticus 18:11', 'Leviticus', 18, 11, 'د یوې ناسکه خور سره زنا مه کوئ، هغه هم ستاسو خور ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus18_verse_11.mp3', '', 1761754199, 1761754199),
(46978, 'Leviticus 18:12', 'Leviticus', 18, 12, 'د خپل پلار د خور سره زنا مه کوئ، هغه ستاسو د پلار نژدې خپلوانه ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus18_verse_12.mp3', '', 1761754199, 1761754199),
(46979, 'Leviticus 18:13', 'Leviticus', 18, 13, 'د خپلې مور د خور سره زنا مه کوئ، ځکه چې هغه ستاسو د مور نژدې خپلوانه ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus18_verse_13.mp3', '', 1761754199, 1761754199),
(46980, 'Leviticus 18:14', 'Leviticus', 18, 14, 'د خپل تره د ښځې سره په زنا کولو د خپل تره سپکاوی مه کوئ، هغه هم ستاسو نژدې خپلوانه ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus18_verse_14.mp3', '', 1761754199, 1761754199),
(46981, 'Leviticus 18:15', 'Leviticus', 18, 15, 'د خپلې انږور سره زنا مه کوئ. هغه ستاسو د زوی ښځه ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus18_verse_15.mp3', '', 1761754199, 1761754199),
(46982, 'Leviticus 18:16', 'Leviticus', 18, 16, 'د خپلې ورېندار سره زنا مه کوئ، دا به ستاسو د ورور دپاره سپکاوی وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus18_verse_16.mp3', '', 1761754199, 1761754199),
(46983, 'Leviticus 18:17', 'Leviticus', 18, 17, 'که تاسو د یوې ښځې سره څملئ، نو د هغې د لور یا د هغې د لمسۍ سره زنا مه کوئ، ځکه چې هغوی د هغې نژدې خپلوان دي. دا ډېر بد کار دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus18_verse_17.mp3', '', 1761754199, 1761754199),
(46984, 'Leviticus 18:18', 'Leviticus', 18, 18, 'ترڅو پورې چې ستاسو ښځې ژوندۍ وي، د خپلو ښینو سره د دوهمې ښځې په توګه واده مه کوئ او د هغوی سره زنا مه کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus18_verse_18.mp3', '', 1761754199, 1761754199),
(46985, 'Leviticus 18:19', 'Leviticus', 18, 19, 'د یوې ښځې سره د هغې د میاشتینۍ ناروغۍ په دوران کې مه یوځای کېږئ، ځکه چې هغه ناپاکه ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus18_verse_19.mp3', '', 1761754199, 1761754199),
(46986, 'Leviticus 18:20', 'Leviticus', 18, 20, 'د بل سړي د ښځې سره زنا مه کوئ او په هغې باندې خپل ځان مه ناپاکه کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus18_verse_20.mp3', '', 1761754199, 1761754199),
(46987, 'Leviticus 18:21', 'Leviticus', 18, 21, 'د خپلو ماشومانو څخه هېڅ یو ماشوم مه ورکوئ چې د مولک د بت دپاره قرباني شي. زه ستاسو څښتن خدای یم او په دې کار به زما سپکاوی وشي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus18_verse_21.mp3', '', 1761754199, 1761754199),
(46988, 'Leviticus 18:22', 'Leviticus', 18, 22, 'هېڅ یو سړی دې د بل سړي سره بد کار نه کوي، د دې څخه خدای کرکه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus18_verse_22.mp3', '', 1761754199, 1761754199),
(46989, 'Leviticus 18:23', 'Leviticus', 18, 23, 'د یو حیوان سره جنسي اړیکې مه ساتئ او په دې ډول په دې کار خپل ځان مه ناپاکه کوئ. یوه ښځه باید یو حیوان ته د جنسي اړیکو په خاطر خپل ځان وړاندې نه کړي، دا ډېر بد کار دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus18_verse_23.mp3', '', 1761754199, 1761754199),
(46990, 'Leviticus 18:24', 'Leviticus', 18, 24, 'په دې عملونو باندې خپل ځانونه مه ناپاکه کوئ، ځکه چې نورو قومونو په دې ډول خپل ځانونه ناپاکه کړل. دا هغه قومونه دي چې په دې خاوره کې اوسیږي او څښتن یې د دې په خاطر وباسي، ترڅو تاسو وکولای شئ چې هغې خاورې ته ورننوځئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus18_verse_24.mp3', '', 1761754199, 1761754199),
(46991, 'Leviticus 18:25', 'Leviticus', 18, 25, 'د هغوی عملونو هغه خاوره ناپاکه کړې ده، نو څښتن هغې خاورې ته سزا ورکوي او هغه مجبوروي چې خپل اوسېدونکي وشړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus18_verse_25.mp3', '', 1761754199, 1761754199),
(46992, 'Leviticus 18:28', 'Leviticus', 18, 28, 'که چېرې تاسو دا ځمکه ناپاکه کړئ، نو هغه به تاسو ایسته وغورځوي لکه څنګه چې ستاسو څخه مخکې قومونه یې غورځولي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus18_verse_28.mp3', '', 1761754199, 1761754199),
(46993, 'Leviticus 18:29', 'Leviticus', 18, 29, 'نو هرڅوک چې د داسې کارونو څخه چې د کرکې وړ دي کوم کار وکړي، نو د خدای د قوم څخه به وشړل شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus18_verse_29.mp3', '', 1761754199, 1761754199),
(46994, 'Leviticus 18:30', 'Leviticus', 18, 30, 'څښتن وویل: «زما امرونو ته غاړه کېږدئ او د هغو د کرکې وړ رواجونو څخه پیروي مه کوئ چې ستاسو د راتګ څخه مخکې به کېدل او په هغو باندې خپل ځانونه مه ناپاکه کوئ. زه ستاسو څښتن خدای یم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus18_verse_30.mp3', '', 1761754199, 1761754199),
(46995, 'Hosea 8:1', 'Hosea', 8, 1, 'څښتن وایي: «د خطر سرنی ووهئ! دښمنان لکه د عقاب په شان زما په وطن باندې غوټې وهي! ځکه چې زما خلکو هغه لوظ مات کړی دی چې د هغوی سره مې کړی ؤ او زما د قوانینو نه یې سرکښي کړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea8_verse_1.mp3', '', 1761754199, 1761754199),
(46996, 'Hosea 8:2', 'Hosea', 8, 2, 'که څه هم هغوی ماته خپل خدای وایي او دعوه کوي چې مونږ اسراییلیان تا پېژنو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea8_verse_2.mp3', '', 1761754199, 1761754199),
(46997, 'Hosea 8:3', 'Hosea', 8, 3, 'خو هغوی هغه لوظ چې ښه دی رد کړی دی، نو په دې سبب د هغوی دښمنان به په هغوی پسې وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea8_verse_3.mp3', '', 1761754199, 1761754199),
(46998, 'Hosea 8:4', 'Hosea', 8, 4, 'زما خلکو پاچاهان وټاکل، خو هغوی دا کار په خپله خوښه وکړ. هغوی مشران وټاکل، خو پرته زما له رضا څخه. هغوی د خپلې تباهۍ په خاطر سپین زر او سره زر واخیستل او بتان یې ورڅخه جوړ کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea8_verse_4.mp3', '', 1761754199, 1761754199),
(46999, 'Hosea 8:5', 'Hosea', 8, 5, 'ای سامریې، زه د هغه طلایي خوسي نه کرکه کوم چې ستا د خلکو له خوا یې عبادت کیږي. زه په هغوی باندې په غضب یم. هغوی به ترڅو پورې د خپلو ګناهونو څخه لاس نه اخلي؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea8_verse_5.mp3', '', 1761754199, 1761754199),
(47000, 'Hosea 8:6', 'Hosea', 8, 6, 'د اسراییلیانو یو کسبګر دا بت جوړ کړی دی او دا بیخي خدای نه دی! هغه طلایي خوسی چې په سامره کې ورته عبادت کیږي، هغه به ټوټې ټوټې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea8_verse_6.mp3', '', 1761754199, 1761754199),
(47001, 'Hosea 8:7', 'Hosea', 8, 7, 'کله چې هغوی باد کري، نو توفان به ورېبي! د غلو دانو بوټي چې وږي ونه لري، نو د هغو نه به اوړه پیدا نه شي. خو که پیدا هم شي، هغه به د پردیو خلکو خوراک شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea8_verse_7.mp3', '', 1761754199, 1761754199),
(47002, 'Hosea 8:8', 'Hosea', 8, 8, 'اسراییلیان په نورو قومونو کې خواره واره شوي دي. هغوی د مات لوښي په شان دي چې کار ورڅخه نه اخیستل کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea8_verse_8.mp3', '', 1761754199, 1761754199),
(47003, 'Hosea 8:9', 'Hosea', 8, 9, 'هغوی د ځنګلي خرو په شان سرګردانه ګرځي او د آشور نه مرسته غواړي. اسراییلیانو د ځانونو د ساتنې دپاره نور قومونه په بیه اخیستي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea8_verse_9.mp3', '', 1761754199, 1761754199),
(47004, 'Hosea 8:10', 'Hosea', 8, 10, 'خو اوس زه اسراییلیان سره راټولوم چې سزا ورته ورکړم. کله چې د آشور پاچا او مامورین په هغوی باندې ظلم وکړي، نو هغوی به ډېر زر په درد باندې اخته شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea8_verse_10.mp3', '', 1761754199, 1761754199),
(47005, 'Hosea 8:11', 'Hosea', 8, 11, 'د اسراییلو خلک چې د خپلو ګناهونو د لېرې کولو دپاره هرڅومره زیاتې قربانګاوې جوړوي، په هماغه اندازه خپلو ځانونو ته د ګناه کولو ځایونه جوړوي!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea8_verse_11.mp3', '', 1761754199, 1761754199),
(47006, 'Hosea 8:12', 'Hosea', 8, 12, 'ما هغوی ته زرګونه قوانین ولیکل، خو هغوی هغه پردي وګڼل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea8_verse_12.mp3', '', 1761754199, 1761754199),
(47007, 'Hosea 8:13', 'Hosea', 8, 13, 'هغوی ماته قربانۍ وړاندې کوي او د قربانیو غوښې خوري. خو زه څښتن د هغوی نه راضي نه یم، نو زه به د هغوی جرمونه رایادوم او د هغوی د ګناهونو په خاطر به ورته سزا ورکوم. هغوی به بېرته مصر ته لاړ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea8_verse_13.mp3', '', 1761754199, 1761754199),
(47008, 'Hosea 8:14', 'Hosea', 8, 14, 'د اسراییلو خلکو ډېرې ماڼۍ‌ګانې جوړې کړې دي، خو هغوی خپل جوړوونکی هېر کړی دی. د یهودا خلکو ډېر قوي ښارونه جوړ کړي دي، خو زه به اور ورباندې نازل کړم چې د هغوی ماڼۍ‌ګانې او قوي ښارونه وسوځوي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea8_verse_14.mp3', '', 1761754199, 1761754199),
(47009, 'Exodus 39:1', 'Exodus', 39, 1, 'د ابي، بانجاني او سرو وړیو څخه هغوی په سپېڅلي ځای کې د خدمت کولو دپاره ښکلي کالي جوړ کړل. هغوی د هارون دپاره هم د څښتن د حکم له مخې چې موسی ته یې کړی ؤ، ځانګړي کالي جوړ کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus39_verse_1.mp3', '', 1761754199, 1761754199),
(47010, 'Exodus 39:2', 'Exodus', 39, 2, 'هغوی د سرو زرو او د ابي، بانجاني او سرو وړیو او د ښه کتان څخه سپېڅلی پېشبند جوړ کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus39_verse_2.mp3', '', 1761754199, 1761754199);